"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["7325"],{8638(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>i,contentTitle:()=>l,toc:()=>h,assets:()=>d});var o=JSON.parse('{"id":"m4-ml-algorithm-toolbox/lesson","title":"Lesson: The ML Algorithm Toolbox \u2014 The AI You Don\'t See","description":"What decided that fraud alert, that loan approval, and which model answered your last prompt?","source":"@site/docs/m4-ml-algorithm-toolbox/lesson.md","sourceDirName":"m4-ml-algorithm-toolbox","slug":"/m4-ml-algorithm-toolbox/lesson","permalink":"/aiml-foundations-site/docs/m4-ml-algorithm-toolbox/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson: The ML Algorithm Toolbox \u2014 The AI You Don\'t See"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/aiml-foundations-site/docs/m3-how-machines-learn/deep-dive"},"next":{"title":"Lab: The ML Algorithm Toolbox \u2014 The AI You Don\'t See","permalink":"/aiml-foundations-site/docs/m4-ml-algorithm-toolbox/lab"}}'),s=n(4848),a=n(8453),r=n(7684);let i={sidebar_position:1,title:"Lesson: The ML Algorithm Toolbox \u2014 The AI You Don't See"},l="The ML Algorithm Toolbox \u2014 The AI You Don't See",d={},h=[{value:"What decided that fraud alert, that loan approval, and which model answered your last prompt?",id:"what-decided-that-fraud-alert-that-loan-approval-and-which-model-answered-your-last-prompt",level:2},{value:"Module slides",id:"module-slides",level:2},{value:"The toolbox, end to end",id:"the-toolbox-end-to-end",level:2},{value:"Linear regression: the model you already built",id:"linear-regression-the-model-you-already-built",level:2},{value:"Logistic regression: the logit an LLM computes for every word",id:"logistic-regression-the-logit-an-llm-computes-for-every-word",level:2},{value:"Decision trees: a flowchart that learns itself",id:"decision-trees-a-flowchart-that-learns-itself",level:2},{value:"Random forests and boosting: why tabular data still belongs to trees",id:"random-forests-and-boosting-why-tabular-data-still-belongs-to-trees",level:2},{value:"The neuron: one weighted decision, stacked into a network",id:"the-neuron-one-weighted-decision-stacked-into-a-network",level:2},{value:"Which algorithm do I use?",id:"which-algorithm-do-i-use",level:2},{value:"What&#39;s next",id:"whats-next",level:2}];function c(e){let t={h1:"h1",h2:"h2",header:"header",mermaid:"mermaid",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"the-ml-algorithm-toolbox--the-ai-you-dont-see",children:"The ML Algorithm Toolbox \u2014 The AI You Don't See"})}),"\n",(0,s.jsx)(t.h2,{id:"what-decided-that-fraud-alert-that-loan-approval-and-which-model-answered-your-last-prompt",children:"What decided that fraud alert, that loan approval, and which model answered your last prompt?"}),"\n",(0,s.jsx)(t.p,{children:"A charge on your card gets flagged as fraud before you even notice it happened. A loan\napplication gets an instant yes or no. A request to an AI product gets routed to a small, cheap\nmodel for a simple question and a bigger, slower one for a hard question. None of those\ndecisions runs on a neural network the size of ChatGPT. They run on a small set of algorithms\nthat are older, cheaper, and \u2014 for the kind of structured, row-and-column data a bank or a\nproduct team actually has \u2014 often better."}),"\n",(0,s.jsx)(t.p,{children:"This module opens that toolbox. You will meet five algorithms you can name and reason about by\nthe end of the lesson, and one of them, a single neuron, turns out to compute the exact same\nmath as every word an LLM produces. By the time Module 5 opens the LLM itself, you will already\nknow the arithmetic running inside it."}),"\n",(0,s.jsx)(t.h2,{id:"module-slides",children:"Module slides"}),"\n",(0,s.jsx)(t.p,{children:"Walk this short whiteboard deck for the big picture before the definitions below, or open it\nfullscreen."}),"\n",(0,s.jsx)(r.A,{src:"decks/m4-ml-algorithm-toolbox.html",title:"M4 \u2014 The ML Algorithm Toolbox"}),"\n",(0,s.jsx)(t.h2,{id:"the-toolbox-end-to-end",children:"The toolbox, end to end"}),"\n",(0,s.jsx)(t.p,{children:"Five algorithms, one thread connecting them: each one is a slightly more capable way of doing\nthe same basic job \u2014 take some inputs, weigh them, and produce an answer. Follow that thread and\nthe neuron at the end stops looking mysterious."}),"\n",(0,s.jsx)(t.mermaid,{value:'graph LR\n    LIN["Linear regression<br/>weighted sum \u2192 a number"] --\x3e LOG["Logistic regression<br/>weighted sum \u2192 a probability<br/>(the logit)"]\n    LOG --\x3e TREE["Decision trees<br/>a flowchart of splits"]\n    TREE --\x3e ENS["Random forests & boosting<br/>many trees, combined"]\n    LOG --\x3e NEURON["A single neuron<br/>weighted sum + activation"]\n    NEURON --\x3e|"stacked into layers"| NET["Neural network<br/>the substrate of everything after this module"]'}),"\n",(0,s.jsx)(t.p,{children:"Keep this shape in mind. Trees and forests are one branch, and that branch still runs the\ntabular data your bank, your fraud team, and your ranking systems depend on. Logistic regression\nand the neuron are the other branch, and that branch is where this module's biggest payoff\nlives."}),"\n",(0,s.jsx)(t.h2,{id:"linear-regression-the-model-you-already-built",children:"Linear regression: the model you already built"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"You already built one of these."})," Module 3's lab trained a model to predict a house's price\nfrom its square footage, bedrooms, and location \u2014 that model was a ",(0,s.jsx)(t.strong,{children:"linear regression"}),". It\ngives every feature a weight, multiplies each feature by its weight, adds the results up, and\nadds one more constant on top. Adjust the weights until that sum lands close to the real price\nacross thousands of examples, and you have a working predictor."]}),"\n",(0,s.jsx)(t.p,{children:"Why you care beyond the lab: that weighted-sum idea \u2014 feature times weight, summed up \u2014 is the\narithmetic core that every other algorithm in this module reuses in some form. Learn it once\nhere and you will keep recognizing it."}),"\n",(0,s.jsx)(t.h2,{id:"logistic-regression-the-logit-an-llm-computes-for-every-word",children:"Logistic regression: the logit an LLM computes for every word"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"}),' picture a loan officer working from a scorecard. Income adds points, a long credit\nhistory adds points, existing debt subtracts points. Add them all up and you get one raw score.\nA linear regression would stop right there and hand you that score as a plain number. A loan\ndecision needs something else \u2014 not "your score is 340," but "an 82% chance of approval."']}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Logistic regression"})," runs the loan officer's weighted sum exactly like linear regression\ndoes, then passes that raw sum through a squashing function called sigmoid, which bends any\nnumber, however large or small, into a value between 0 and 1 \u2014 a probability. That raw sum,\nbefore the squashing, has a name: the ",(0,s.jsx)(t.strong,{children:"logit"}),". Remember that word, because here is the payoff\nof this whole section: an LLM computes a logit for every single word it could say next. For each\ncandidate word in its vocabulary, it runs the same weighted-sum arithmetic you just saw in the\nloan officer's scorecard, gets one raw logit per candidate, then squashes the whole set of them\n\u2014 this time with sigmoid's multi-option cousin, softmax \u2014 into a probability distribution over\nevery word it could pick. Then it samples one. Predicting the next word in a sentence and\napproving a loan application run on the same underlying math: logistic regression, just aimed at\na vocabulary of tens of thousands of words instead of two outcomes."]}),"\n",(0,s.jsx)(t.h2,{id:"decision-trees-a-flowchart-that-learns-itself",children:"Decision trees: a flowchart that learns itself"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"})," think about a helpdesk troubleshooting flowchart. Is it plugged in? If no, plug it\nin. If yes, is the outlet working? Each answer sends you down a different branch until you land\non an actual fix."]}),"\n",(0,s.jsxs)(t.p,{children:["A ",(0,s.jsx)(t.strong,{children:"decision tree"}),' is that flowchart, except the questions ("is income above X?", "is this\ntransaction amount above Y?") and the order they get asked in are learned from data, not written\nby a person. At each step, the tree finds the single split of the data that separates the\noutcomes best, asks that question, and repeats on each half, until it reaches a ',(0,s.jsx)(t.strong,{children:"leaf"})," \u2014 a\nfinal prediction. The result is a model you can trace, question by question, to see exactly why\nit made the call it made."]}),"\n",(0,s.jsx)(t.h2,{id:"random-forests-and-boosting-why-tabular-data-still-belongs-to-trees",children:"Random forests and boosting: why tabular data still belongs to trees"}),"\n",(0,s.jsx)(t.p,{children:"One tree overfits easily. Let it ask enough narrow, specific questions and it will happily\nmemorize your training data instead of the real pattern \u2014 Module 3's overfitting problem,\nshowing up again. Two fixes for that, and both are still built from trees."}),"\n",(0,s.jsxs)(t.p,{children:["A ",(0,s.jsx)(t.strong,{children:"random forest"})," trains many trees, each one on a random slice of the data and a random\nsubset of the features, then averages their answers. No single tree gets the final say. It is a\npanel of judges, not one judge, so an outlier in any one tree gets outvoted by the rest."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Boosting"})," \u2014 the idea behind tools like XGBoost and LightGBM \u2014 builds trees one after another\ninstead of in parallel, and each new tree is trained specifically to fix the mistakes the ones\nbefore it made. It is a chain of editors, where each pass focuses only on what the last pass got\nwrong."]}),"\n",(0,s.jsx)(t.p,{children:"Why you care: on rows-and-columns data, boosted trees and random forests still beat neural\nnetworks on accuracy most of the time, and they need far less data to get there. That is why\nfraud detection systems, search and ad ranking, and the router that decides which model answers\nyour prompt inside a multi-model AI product are usually running a forest or a boosted tree, not\na neural network. Neural networks earn their keep on images, audio, and text \u2014 raw, unstructured\nsignal. Structured business data is still tree territory."}),"\n",(0,s.jsx)(t.h2,{id:"the-neuron-one-weighted-decision-stacked-into-a-network",children:"The neuron: one weighted decision, stacked into a network"}),"\n",(0,s.jsxs)(t.p,{children:["Look back at logistic regression's shape: a weighted sum, then a squashing function. That is\nalso, exactly, what a single ",(0,s.jsx)(t.strong,{children:"neuron"})," computes. Give a neuron some inputs, and it multiplies\neach one by a weight, adds a bias, and passes the total through an ",(0,s.jsx)(t.strong,{children:"activation function"})," \u2014\nsigmoid is one choice, but a simpler one called ReLU (it just outputs the number itself when\npositive, and zero otherwise) is more common in practice. One neuron, by itself, is a logistic\nregression wearing a different name."]}),"\n",(0,s.jsxs)(t.p,{children:["The part that matters is what happens when you stack them. Take a layer of neurons, feed every\ninput to every one of them, and feed all of their outputs forward as the inputs to the next\nlayer. Each layer learns to combine what the layer before it noticed into something a little\nmore abstract \u2014 early layers respond to simple patterns, later layers combine those into\nsomething closer to the actual answer you want. That stack is a ",(0,s.jsx)(t.strong,{children:"neural network"}),", and it is\nthe one piece of this toolbox that keeps scaling: add more layers, more neurons per layer, more\ntraining data, and it keeps getting more capable in a way a single tree or a single logistic\nregression does not. Every model you touch for the rest of this course \u2014 today's digit\nclassifier, and every LLM from Module 5 onward \u2014 is this same stack of weighted sums and\nsquashing functions, just far bigger. This is the substrate of everything that follows."]}),"\n",(0,s.jsx)(t.h2,{id:"which-algorithm-do-i-use",children:"Which algorithm do I use?"}),"\n",(0,s.jsxs)(t.table,{children:[(0,s.jsx)(t.thead,{children:(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.th,{children:"Your data looks like..."}),(0,s.jsx)(t.th,{children:"Reach for"}),(0,s.jsx)(t.th,{children:"Why"})]})}),(0,s.jsxs)(t.tbody,{children:[(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Rows and columns, predict a number"}),(0,s.jsx)(t.td,{children:"Linear regression"}),(0,s.jsx)(t.td,{children:"Simple, fast, and a strong first baseline"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Rows and columns, predict yes/no or a category"}),(0,s.jsx)(t.td,{children:"Logistic regression"}),(0,s.jsx)(t.td,{children:"Fast, interpretable, and gives you a real probability"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Rows and columns, need to explain the exact reasoning"}),(0,s.jsx)(t.td,{children:"A decision tree"}),(0,s.jsx)(t.td,{children:"You can trace the decision, question by question"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Rows and columns, need the best accuracy you can get"}),(0,s.jsx)(t.td,{children:"Random forest or boosting"}),(0,s.jsx)(t.td,{children:"Usually wins on tabular data \u2014 fraud, ranking, routing"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Images, audio, raw text"}),(0,s.jsx)(t.td,{children:"A neural network"}),(0,s.jsx)(t.td,{children:"Learns its own features from unstructured signal"})]})]})]}),"\n",(0,s.jsx)(t.h2,{id:"whats-next",children:"What's next"}),"\n",(0,s.jsx)(t.p,{children:"You now know the arithmetic sitting under logistic regression and a single neuron: a weighted\nsum, then a squashing function, turning raw scores into probabilities. Module 5 takes that exact\nsame logit and scales it up into a full language model \u2014 tokens, transformers, and the sampling\nstep that turns a distribution of logits into the next word on your screen."})]})}function u(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},7684(e,t,n){n.d(t,{A:()=>a});var o=n(4848);n(6540);var s=n(6497);function a({src:e,title:t="Slides"}){let n=(0,s.Ay)(e);return(0,o.jsxs)("div",{className:"deck_nWXz",children:[(0,o.jsxs)("div",{className:"bar_dOoE",children:[(0,o.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",t]}),(0,o.jsx)("a",{className:"full_PrDQ",href:n,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,o.jsx)("div",{className:"frame_M4DO",children:(0,o.jsx)("iframe",{src:n,title:t,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>i});var o=n(6540);let s={},a=o.createContext(s);function r(e){let t=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),o.createElement(a.Provider,{value:t},e.children)}}}]);